"""Test Result generated by autotest."""
from __future__ import print_function

import datetime
import json
import logging  # pylint: disable=cros-logging-import
import os
import pathlib
import re

import test_result_interface
from moblab_common import afe_connector

ROOT_DIR = pathlib.Path('/usr/local/autotest/results')

_LOGGER = logging.getLogger(pathlib.Path(__file__).stem)
_TIMESTAMP_FORMAT = '%Y-%m-%d %H:%M:%S'
_STATUS_LOG = 'status.log'


def _query_speical_task_finished_time(id_):
    """Query AFE with task id and yield the finished time."""
    afe = afe_connector.AFEConnector()
    while True:
        result = afe.get_special_tasks([id_])
        if not result:
            raise test_result_interface.TestResultError(
                'Failed to query AFE special task {}'.format(id_)
            )

        result = result[0]
        yield datetime.datetime.strptime(result['time_finished'],
                                         _TIMESTAMP_FORMAT)


def _query_job_finished_time(id_):
    """Query AFE with job id and yield the finished time."""
    afe = afe_connector.AFEConnector()
    while True:
        result = afe.get_jobs([id_])
        if not result:
            raise test_result_interface.TestResultError(
                'Failed to query AFE special task {}'.format(id_)
            )
        result = result[0]
        hqes = afe.get_host_queue_entries(id_)
        if not hqes:  # For data inconsistency.
            yield datetime.datetime.strptime(result['created_on'],
                                             _TIMESTAMP_FORMAT)

        finished_time = max([datetime.datetime.strptime(hqe['finished_on'],
                                                        _TIMESTAMP_FORMAT)
                             for hqe in hqes])
        yield finished_time


class _AutotestResult(test_result_interface.TestResult):
    """Base class for Autotest job and special tasks."""

    def __init__(self, *, description, root_dir, relative_path):
        super().__init__(description=description, root_dir=root_dir,
                         relative_path=relative_path)
        # TODO(guocb) Cache the data to a local disk file.
        self._finished_time = None
        self._succeeded = None
        self._afe_query = None

    @property
    def id(self):
        return self._id

    @property
    def finished_time(self):
        if not self._finished_time:
            self._finished_time = next(self._afe_query)

        return self._finished_time

    @property
    def succeeded(self):
        """Check status.log to figure out the job/task exit status."""
        if self._succeeded is not None:
            return self._succeeded

        try:
            with open(self.abs_path / _STATUS_LOG) as f:
                for line in f:
                    if not line.startswith('END '):
                        continue
                    exit_status = line.split(maxsplit=2)[1]
                    self._succeeded = (exit_status == 'GOOD')
                    return self._succeeded

        except (FileNotFoundError, IndexError):
            return None


class AutotestHostTask(_AutotestResult):
    """A class to represent autotest host tasks."""
    GLOB_PATTERN = 'hosts/*/[0-9]*-*'
    REGEX_PATTERN = r'^hosts/[^/]+/(?P<id>(?P<afe_id>\d+)-\S+)$'

    def __init__(self, *, root_dir, relative_path):
        super().__init__(description='Autotest host task', root_dir=root_dir,
                         relative_path=relative_path)
        m = re.match(self.REGEX_PATTERN, str(relative_path))
        if not m:
            raise test_result_interface.TestResultError(
                'Can\'t get id of {}'.format(self))

        self._id = m.group('id')
        self._afe_query = _query_speical_task_finished_time(m.group('afe_id'))


class AutotestTestJob(_AutotestResult):
    """A class to represent autotest test job."""
    GLOB_PATTERN = '[0-9]*-*'
    REGEX_PATTERN = r'(?P<afe_id>\d+)-\S+'

    def __init__(self, *, root_dir, relative_path):
        super().__init__(description='Autotest job', root_dir=root_dir,
                         relative_path=relative_path)
        m = re.match(self.REGEX_PATTERN, str(relative_path))
        if not m:
            raise test_result_interface.TestResultError(
                'Can\'t get id of {}'.format(self))

        self._id = relative_path
        self._afe_query = _query_job_finished_time(m.group('afe_id'))
